/* Framer Motion Replica Engine */
.fm-motion {
    opacity: 0;
    transform: translateY(50px) scale(0.96);
    transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1), transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
    will-change: opacity, transform;
}
.fm-motion.fm-in-view {
    opacity: 1;
    transform: translateY(0) scale(1);
}
.fm-delay-1 { transition-delay: 0.12s; }
.fm-delay-2 { transition-delay: 0.24s; }
.fm-delay-3 { transition-delay: 0.36s; }
.fm-delay-4 { transition-delay: 0.48s; }

/* Grand Envelope Opening Animation */
.si-envelope-overlay {
    transition: opacity 1.1s cubic-bezier(0.16, 1, 0.3, 1), transform 1.1s cubic-bezier(0.16, 1, 0.3, 1), visibility 1.1s ease !important;
}
.si-envelope-overlay.si-opening {
    opacity: 0 !important;
    transform: scale(1.08) translateY(-30px) !important;
    pointer-events: none !important;
}
.si-envelope-overlay.si-opening .si-envelope-scene {
    transform: scale(0.95) translateY(-40px);
    transition: transform 1.1s cubic-bezier(0.16, 1, 0.3, 1);
}
.si-envelope-overlay.si-opening .si-ec__gopuram-footer {
    transform: translateY(100px);
    transition: transform 1.1s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Curtain Opening Animation */
.km-entry {
    transition: opacity 1.1s cubic-bezier(0.16, 1, 0.3, 1), visibility 1.1s ease !important;
}
.km-entry.km-closing {
    opacity: 0 !important;
    pointer-events: none !important;
}
.km-entry.km-closing .km-entry__card {
    transform: translate(-50%, 60%) scale(0.88) !important;
    transition: transform 1.1s cubic-bezier(0.16, 1, 0.3, 1) !important;
}
.km-entry.km-closing .km-entry__veil {
    opacity: 0 !important;
    transition: opacity 1.1s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

/* Floating & Rotating Continuous Animations */
@keyframes fm-float {
    0%, 100% { transform: translateY(0px) rotate(0deg); }
    50% { transform: translateY(-10px) rotate(2deg); }
}
@keyframes fm-spin-slow {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}
.si-couple__wreath { animation: fm-spin-slow 90s linear infinite !important; }
.si-deco__mandala-right, .si-deco__mandala-left { animation: fm-spin-slow 80s linear infinite !important; }
